<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientDefaultAcrValuesAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientDefaultAcrValuesAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientDefaultAcrValuesAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getDefaultAcrValues returns null on a freshly created holder.
     */
    public function testDefaultAcrValuesNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDefaultAcrValuesAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isDefaultAcrValuesAssigned());
        $this->assertNull($holder->getDefaultAcrValues());
    }
}
class ImplWithTrustedClientDefaultAcrValuesAttributeHolderUnitTest
{
    use TrustedClientDefaultAcrValuesAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedDefaultAcrValuesRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultDefaultAcrValues();
    }
}
